package org.eclipse.rdf4j.http.client;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.junit.jupiter.api.Test;

class CancellableOperationCoordinatorTest {

	@Test
	void rejectsDuplicateActiveIdsAndAllowsReuseAfterCompletion() {
		CancellableOperationCoordinator coordinator = new CancellableOperationCoordinator();
		CancellableOperationCoordinator.Handle first = coordinator.register("request-1");

		assertThatThrownBy(() -> coordinator.register("request-1"))
				.isInstanceOf(IllegalStateException.class)
				.hasMessage("Request already active: request-1");

		coordinator.complete(first);
		CancellableOperationCoordinator.Handle second = coordinator.register("request-1");

		assertThat(second).isNotSameAs(first);
		coordinator.complete(second);
	}

	@Test
	void rejectsBlankIdsAndNormalizesRegisteredIds() {
		CancellableOperationCoordinator coordinator = new CancellableOperationCoordinator();

		assertThatThrownBy(() -> coordinator.register("   "))
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessage("Request id was blank");

		CancellableOperationCoordinator.Handle handle = coordinator.register(" request-1 ");
		assertThat(handle.getRequestId()).isEqualTo("request-1");
		assertThat(coordinator.cancel(" request-1 ")).isTrue();
	}

	@Test
	void cancelBeforeAttachmentSkipsOperation() throws Exception {
		CancellableOperationCoordinator coordinator = new CancellableOperationCoordinator();
		CancellableOperationCoordinator.Handle handle = coordinator.register("request-2");
		RepositoryConnection connection = mock(RepositoryConnection.class);
		AtomicBoolean executed = new AtomicBoolean();

		assertThat(coordinator.cancel("request-2")).isTrue();
		assertThat(coordinator.execute(handle, connection, () -> {
			executed.set(true);
			return "unexpected";
		})).isNull();

		assertThat(executed).isFalse();
		verify(connection, never()).close();
	}

	@Test
	void cancelInterruptsWorkerClosesConnectionAndForwardsOnce() throws Exception {
		CancellableOperationCoordinator coordinator = new CancellableOperationCoordinator();
		RepositoryConnection connection = mock(RepositoryConnection.class);
		AtomicInteger forwarded = new AtomicInteger();
		CancellableOperationCoordinator.Handle handle = coordinator.register("request-3", forwarded::incrementAndGet);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		CountDownLatch started = new CountDownLatch(1);
		CountDownLatch interrupted = new CountDownLatch(1);

		try {
			Future<?> future = executor.submit(() -> {
				try {
					coordinator.execute(handle, connection, () -> {
						started.countDown();
						try {
							new CountDownLatch(1).await();
						} catch (InterruptedException e) {
							interrupted.countDown();
						}
						return null;
					});
				} finally {
					coordinator.complete(handle);
				}
				return null;
			});

			assertThat(started.await(5, TimeUnit.SECONDS)).isTrue();
			assertThat(coordinator.cancel("request-3")).isTrue();
			assertThat(coordinator.cancel("request-3")).isFalse();
			future.get(5, TimeUnit.SECONDS);

			assertThat(interrupted.await(5, TimeUnit.SECONDS)).isTrue();
			assertThat(handle.isActive()).isFalse();
			assertThat(forwarded).hasValue(1);
			verify(connection, times(1)).close();
		} finally {
			executor.shutdownNow();
		}
	}

	@Test
	void completedOperationDoesNotRunCancellationActions() {
		CancellableOperationCoordinator coordinator = new CancellableOperationCoordinator();
		RepositoryConnection connection = mock(RepositoryConnection.class);
		AtomicInteger forwarded = new AtomicInteger();
		CancellableOperationCoordinator.Handle handle = coordinator.register("request-4", forwarded::incrementAndGet);

		coordinator.complete(handle);

		assertThat(coordinator.cancel("request-4")).isFalse();
		assertThat(forwarded).hasValue(0);
		verify(connection, never()).close();
	}

	@Test
	void shutdownCancelsEveryActiveOperation() {
		CancellableOperationCoordinator coordinator = new CancellableOperationCoordinator();
		AtomicInteger forwarded = new AtomicInteger();
		CancellableOperationCoordinator.Handle first = coordinator.register("request-5", forwarded::incrementAndGet);
		CancellableOperationCoordinator.Handle second = coordinator.register("request-6", forwarded::incrementAndGet);

		coordinator.shutdown();

		assertThat(first.isActive()).isFalse();
		assertThat(second.isActive()).isFalse();
		assertThat(forwarded).hasValue(2);
		assertThat(coordinator.cancel("request-5")).isFalse();
		assertThat(coordinator.cancel("request-6")).isFalse();
	}
}
